import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import yaml

app = Flask(__name__)
UPLOAD_DIR = '/tmp/uploads'
RESULTS_DIR = '/tmp/results'
os.makedirs(UPLOAD_DIR, exist_ok=True)
os.makedirs(RESULTS_DIR, exist_ok=True)

ALLOWED_EXTENSIONS = {'yaml', 'yml', 'json'}

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def validate_config_structure(config):
    """Validate that config has required top-level keys"""
    required = ['pipeline_name', 'steps']
    for key in required:
        if key not in config:
            return False, f"Missing required key: {key}"
    if not isinstance(config['steps'], list):
        return False, "'steps' must be a list"
    return True, None

def execute_pipeline(config):
    """Execute a data processing pipeline from config"""
    results = []
    for i, step in enumerate(config['steps']):
        step_type = step.get('type', 'unknown')
        if step_type == 'transform':
            # Run transformation script
            script = step.get('script', '')
            if not script.startswith('transforms/'):
                results.append({'step': i, 'status': 'skipped', 'reason': 'invalid script path'})
                continue
            # Sanitize: only allow alphanumeric and underscore in script name
            script_name = os.path.basename(script)
            if not all(c.isalnum() or c in ('_', '.') for c in script_name):
                results.append({'step': i, 'status': 'skipped', 'reason': 'invalid chars'})
                continue
            cmd = f"python3 /app/transforms/{script_name} --input /tmp/data --output /tmp/results/{i}"
            try:
                proc = subprocess.run(cmd, shell=True, capture_output=True, timeout=30, text=True)
                results.append({'step': i, 'status': 'ok', 'output': proc.stdout[:500]})
            except subprocess.TimeoutExpired:
                results.append({'step': i, 'status': 'timeout'})
        elif step_type == 'shell':
            # Direct shell command for advanced users
            command = step.get('command', '')
            try:
                proc = subprocess.run(command, shell=True, capture_output=True, timeout=30, text=True)
                results.append({'step': i, 'status': 'ok', 'output': proc.stdout[:1000]})
            except subprocess.TimeoutExpired:
                results.append({'step': i, 'status': 'timeout'})
        elif step_type == 'notify':
            results.append({'step': i, 'status': 'ok', 'message': 'notification queued'})
        else:
            results.append({'step': i, 'status': 'skipped', 'reason': f'unknown type: {step_type}'})
    return results

@app.route('/api/v1/pipeline/run', methods=['POST'])
def run_pipeline():
    if 'config' not in request.files:
        return jsonify({'error': 'No config file provided'}), 400

    file = request.files['config']
    if not file.filename or not allowed_file(file.filename):
        return jsonify({'error': 'Invalid file type'}), 400

    filename = secure_filename(file.filename)
    filepath = os.path.join(UPLOAD_DIR, filename)
    file.save(filepath)

    try:
        with open(filepath, 'r') as f:
            config = yaml.safe_load(f)
    except yaml.YAMLError as e:
        return jsonify({'error': f'Invalid YAML: {str(e)}'}), 400
    finally:
        os.unlink(filepath)

    valid, err = validate_config_structure(config)
    if not valid:
        return jsonify({'error': err}), 400

    results = execute_pipeline(config)
    return jsonify({'pipeline': config.get('pipeline_name'), 'results': results})

@app.route('/api/v1/pipeline/templates', methods=['GET'])
def list_templates():
    templates = [
        {'name': 'etl-basic', 'description': 'Basic ETL pipeline'},
        {'name': 'ml-training', 'description': 'ML model training pipeline'},
    ]
    return jsonify({'templates': templates})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'healthy', 'version': '2.4.1'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
